{"path": "/tmp/sv-e059a387c95445359c81005c5bb6808d/Components/Pages/Chat/MessageArea.razor", "file_text": "@namespace sv_e059a387c95445359c81005c5bb6808d.Components.Pages.Chat

<div class="message-area">
    @if (Channel is not null)
    {
        <div class="message-area-header">
            <h5># @Channel.Name</h5>
            <span class="channel-description">@Channel.Description</span>
        </div>

        <div class="message-list" @onscroll="HandleScroll" @ref="_messageListRef">
            @if (IsLoadingMore)
            {
                <div class="loading-indicator">Loading older messages…</div>
            }
            @foreach (var message in Messages)
            {
                var threadInfo = ThreadSummaries.FirstOrDefault(t => t.RootMessageId == message.Id);
                <MessageItem Message="message"
                             IsThreadStarter="threadInfo is not null"
                             ReplyCount="threadInfo?.ReplyCount ?? 0"
                             OnOpenThread="OnOpenThread"
                             OnReact="(emoji) => OnReact.InvokeAsync((message.Id, emoji))" />
            }
        </div>

        <div class="message-input-area">
            <textarea class="form-control message-textarea"
                      placeholder="Message #@Channel.Name"
                      @bind="NewMessageText"
                      @bind:event="oninput"
                      @onkeydown="HandleKeyDown"
                      rows="2"></textarea>
            <button class="btn btn-primary send-btn" @onclick="SendMessage" disabled="@string.IsNullOrWhiteSpace(NewMessageText)">
                Send
            </button>
        </div>
    }
    else
    {
        <div class="no-channel-selected">
            <p>Select a channel to start chatting</p>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public Services.Channel? Channel { get; set; }

    [Parameter, EditorRequired]
    public List<Services.Message> Messages { get; set; } = [];

    [Parameter]
    public List<ThreadSummary> ThreadSummaries { get; set; } = [];

    [Parameter]
    public bool IsLoadingMore { get; set; }

    [Parameter]
    public EventCallback<int> OnOpenThread { get; set; }

    [Parameter]
    public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    [Parameter]
    public EventCallback<string> OnSendMessage { get; set; }

    [Parameter]
    public EventCallback OnLoadMore { get; set; }

    private string NewMessageText { get; set; } = string.Empty;
    private ElementReference _messageListRef;

    private async Task SendMessage()
    {
        if (string.IsNullOrWhiteSpace(NewMessageText)) return;
        var text = NewMessageText;
        NewMessageText = string.Empty;
        await OnSendMessage.InvokeAsync(text);
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendMessage();
        }
    }

    private async Task HandleScroll(EventArgs e)
    {
        // Scroll-to-top detection is handled via JS interop in a production app.
        // For now, we expose the OnLoadMore callback for parent orchestration.
        await Task.CompletedTask;
    }
}
"}

