toolArgs.file_text:
.message-item {
    padding: 8px 16px;
    position: relative;
    border-radius: 4px;
}

.message-item:hover {
    background: var(--bs-tertiary-bg);
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.message-author {
    font-weight: 700;
    font-size: 0.95rem;
}

.message-time {
    font-size: 0.75rem;
    color: var(--bs-secondary-color);
}

.message-content {
    font-size: 0.9rem;
    line-height: 1.5;
    white-space: pre-wrap;
    word-wrap: break-word;
}

.message-reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 4px;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 2px 8px;
    border-radius: 12px;
    font-size: 0.8rem;
    background: var(--bs-tertiary-bg);
    border: 1px solid var(--bs-border-color);
    cursor: pointer;
}

.reaction-badge:hover {
    background: var(--bs-primary-bg-subtle);
    border-color: var(--bs-primary);
}

.thread-link {
    display: inline-block;
    margin-top: 4px;
    padding: 2px 0;
    border: none;
    background: transparent;
    color: var(--bs-primary);
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: -8px;
    right: 16px;
    display: flex;
    gap: 2px;
    background: var(--bs-body-bg);
    border: 1px solid var(--bs-border-color);
    border-radius: 6px;
    padding: 2px 4px;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.1);
}

.action-btn {
    border: none;
    background: transparent;
    padding: 4px 8px;
    border-radius: 4px;
    font-size: 0.8rem;
    cursor: pointer;
    white-space: nowrap;
}

.action-btn:hover {
    background: var(--bs-tertiary-bg);
}

.react-action-wrapper {
    position: relative;
}

.thread-starter {
    border-left: 3px solid var(--bs-primary);
}

