toolArgs.file_text:
@namespace sv_e059a387c95445359c81005c5bb6808d.Components.Pages.Chat

<div class="channel-list">
    <div class="channel-list-header">
        <h6>Channels</h6>
    </div>
    <div class="channel-items">
        @foreach (var channel in Channels)
        {
            <button class="channel-item @(channel.Id == ActiveChannelId ? "active" : "")"
                    @onclick="() => OnChannelSelected.InvokeAsync(channel.Id)">
                <div class="channel-name-row">
                    <span class="channel-name"># @channel.Name</span>
                    @if (channel.UnreadCount > 0)
                    {
                        <span class="unread-badge">@channel.UnreadCount</span>
                    }
                </div>
                @if (!string.IsNullOrWhiteSpace(channel.Description))
                {
                    <span class="channel-desc">@Truncate(channel.Description, 40)</span>
                }
            </button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public List<Services.Channel> Channels { get; set; } = [];

    [Parameter]
    public int ActiveChannelId { get; set; }

    [Parameter]
    public EventCallback<int> OnChannelSelected { get; set; }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..maxLength] + "…";
}

.channel-list {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: var(--bs-dark-bg-subtle);
    border-right: 1px solid var(--bs-border-color);
}

.channel-list-header {
    padding: 16px 16px 8px;
    border-bottom: 1px solid var(--bs-border-color);
}

.channel-list-header h6 {
    margin: 0;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.75rem;
    letter-spacing: 0.05em;
    color: var(--bs-secondary-color);
}

.channel-items {
    flex: 1;
    overflow-y: auto;
    padding: 8px;
}

.channel-item {
    display: block;
    width: 100%;
    text-align: left;
    padding: 8px 12px;
    border: none;
    background: transparent;
    border-radius: 6px;
