.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    border-left: 1px solid var(--bs-border-color);
    background: var(--bs-body-bg);
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    border-bottom: 1px solid var(--bs-border-color);
}

.thread-header h6 {
    margin: 0;
    font-weight: 700;
}

.thread-root-message {
    padding: 12px 16px;
    background: var(--bs-tertiary-bg);
    border-bottom: 1px solid var(--bs-border-color);
}

.root-author {
    font-weight: 700;
    font-size: 0.85rem;
    margin-bottom: 4px;
}

.root-content {
    font-size: 0.85rem;
    white-space: pre-wrap;
    word-wrap: break-word;
}

.thread-divider {
    padding: 8px 16px;
    font-size: 0.75rem;
    color: var(--bs-secondary-color);
    border-bottom: 1px solid var(--bs-border-color);
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.thread-reply {
    padding: 8px 16px;
}

.thread-reply:hover {
    background: var(--bs-tertiary-bg);
}

.reply-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.reply-author {
    font-weight: 700;
    font-size: 0.85rem;
}

.reply-time {
    font-size: 0.7rem;
    color: var(--bs-secondary-color);
}

.reply-content {
    font-size: 0.85rem;
    white-space: pre-wrap;
    word-wrap: break-word;
}

.thread-input-area {
    display: flex;
    gap: 8px;
    padding: 12px 16px;
    border-top: 1px solid var(--bs-border-color);
    align-items: flex-end;
}

.thread-textarea {
    flex: 1;
    resize: none;
    font-size: 0.85rem;
}

.reply-btn {
    flex-shrink: 0;
}

